# ======== src/dialbench_metrics.py ========
"""DialBench / RPM-10K official metric, ported verbatim from the authors' evaluation script.

Source: https://github.com/Event-AHU/DialBench  benchmark/benchmark.py  (functions
`extract_last_number`, `load_data`, and the accumulation inside `main` + `calculate_metrics`).
Fetched 2026-10-07; repo default branch `main`, pushed_at 2026-08-27.

Definitions as implemented there (not as the prose of the paper, where "Ref" and "Rel"
are described loosely):
  error      = |pred - gt|
  Acc_eps    = mean( error <= 0.01 * range )                    over ALL samples
  Acc_theta  = mean( error / gt < 0.05 )                        over samples with gt != 0
  Ref (Gamma)= mean( min(error / range, 10) )                   (clip at 10)
  Rel (Theta)= mean( min(error / gt, 100) )                     over samples with gt != 0 (clip at 100)

Notes kept from the authors' code on purpose:
  * the ground truth is `extract_last_number(str(item['reading']))` (last number in the string);
  * `range` is read from the annotation file and is used ONLY to scale epsilon, never fed to the model;
  * a missing number in a prediction becomes 0.0.
This module has no torch dependency so the same file runs on the Mac and in Kaggle kernels.
"""
import re
import numpy as np

_NUM = re.compile(r"[-+]?\d*\.\d+|[-+]?\d+")


def extract_last_number(text):
    """Last int/float in a string (authors' regex). Returns 0.0 if none."""
    matches = _NUM.findall(str(text))
    if matches:
        return float(matches[-1])
    return 0.0


def dialbench_metrics(pred, gt, rng):
    """pred, gt, rng: 1-D float arrays. Returns dict with the four authors' metrics (fractions, not %)."""
    pred = np.asarray(pred, dtype=np.float64)
    gt = np.asarray(gt, dtype=np.float64)
    rng = np.asarray(rng, dtype=np.float64)
    n = len(gt)
    err = np.abs(pred - gt)
    eps = 0.01 * rng
    acc_eps_hits = err <= eps  # same `<=` as the authors' code
    nz = gt != 0
    theta = err[nz] / gt[nz]
    out = {
        "n": int(n),
        "acc_eps": float(acc_eps_hits.sum() / n) if n else None,
        "acc_theta": float((theta < 0.05).sum() / nz.sum()) if nz.sum() else None,
        "ref": float(np.mean(np.clip(err / rng, None, 10))) if n else None,
        "rel": float(np.mean(np.clip(theta, None, 100))) if nz.sum() else None,
        "n_nonzero_gt": int(nz.sum()),
    }
    return out


def wilson_interval(k, n, z=1.959964):
    """95% Wilson score interval for a binomial proportion k/n."""
    if n == 0:
        return (float("nan"), float("nan"))
    p = k / n
    d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * np.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return (float(c - h), float(c + h))


def bootstrap_acc_ci(hits, n_boot=2000, seed=0, groups=None):
    """Percentile bootstrap CI for a mean of 0/1 hits. If `groups` is given, resample whole groups
    (use for frames from the same video / meter instance, which are not independent)."""
    rs = np.random.RandomState(seed)
    hits = np.asarray(hits, dtype=np.float64)
    if groups is None:
        idx = rs.randint(0, len(hits), size=(n_boot, len(hits)))
        means = hits[idx].mean(1)
    else:
        groups = np.asarray(groups)
        uniq, inv = np.unique(groups, return_inverse=True)
        sums = np.bincount(inv, weights=hits, minlength=len(uniq))
        cnts = np.bincount(inv, minlength=len(uniq)).astype(np.float64)
        gi = rs.randint(0, len(uniq), size=(n_boot, len(uniq)))
        means = sums[gi].sum(1) / cnts[gi].sum(1)
    return float(np.percentile(means, 2.5)), float(np.percentile(means, 97.5))

# ======== src/rpm_common.py ========
# Framework-free data logic for RPM-10K / DialBench: label parsing, targets, bins, decoders, splits, scoring.
# Design statistics come from labels/train.json only. labels/test.json `range` and `meter_type` are scorer/report-only.
import json
import re
import numpy as np

NUM_RE = re.compile(r"[-+]?\d*\.\d+|[-+]?\d+")
DETAIL_RANGE_RE = re.compile(
    r"(?:range|ranges|scale)[^0-9\-]{0,40}(?:from\s*)?(-?\d+(?:\.\d+)?)\s*(?:to|-|~)\s*(-?\d+(?:\.\d+)?)", re.I)


def last_num(t):
    m = NUM_RE.findall(str(t))
    return float(m[-1]) if m else 0.0  # identical to the official extract_last_number (0.0 if no number)


def span_from_train_row(it):
    """Span (full-scale value, lo==0) for a train.json row, or nan if unknown.
    1) `range` string "0-3"/"0-6"/"0-10"  2) fall back to the (lo,hi) found in the CoT `detail` text when lo==0."""
    rg = it.get("range")
    if isinstance(rg, str) and "-" in rg:
        try:
            lo, hi = rg.split("-")[0], rg.split("-")[-1]
            if float(lo) == 0 and float(hi) > 0:
                return float(hi), "range_field"
        except Exception:
            pass
    m = DETAIL_RANGE_RE.search(str(it.get("detail", "")))
    if m:
        lo, hi = float(m.group(1)), float(m.group(2))
        if lo == 0 and hi > 0:
            return hi, "detail_parse"
    return float("nan"), "unknown"


def family_of_train_row(it):
    """Coarse dial family from train.json fields (train has no meter_type)."""
    rg = it.get("range")
    if isinstance(rg, str):
        ks = json.dumps(it.get("key scale"))
        return f"{rg}|{it.get('graduation value')}|{ks}"
    return "others"


class Targets:
    """Bin grid + span classes (built from train spans only)."""

    def __init__(self, train_spans, y_min=-0.01, y_max=1.25, bin_w=0.0025, min_class_count=20):
        self.y_min, self.y_max, self.bin_w = y_min, y_max, bin_w
        self.nb = int(round((y_max - y_min) / bin_w)) + 1
        self.centers = y_min + bin_w * np.arange(self.nb)
        sp = np.asarray(train_spans, dtype=np.float64)
        sp = sp[~np.isnan(sp)]
        vals, cnt = np.unique(np.round(sp, 4), return_counts=True)
        self.span_vals = vals[cnt >= min_class_count]
        self.rare_span = float(np.median(sp[~np.isin(np.round(sp, 4), self.span_vals)])) if (~np.isin(np.round(sp, 4), self.span_vals)).any() else 100.0
        self.ns = len(self.span_vals) + 1  # last class = rare

    def span_class(self, span):
        span = np.asarray(span, dtype=np.float64)
        out = np.full(span.shape, -1, np.int64)
        ok = ~np.isnan(span)
        d = np.abs(np.round(span, 4)[..., None] - self.span_vals[None, :]) if len(self.span_vals) else None
        hit = (d < 1e-6) if d is not None else np.zeros(span.shape + (0,), bool)
        cls = np.where(hit.any(-1), hit.argmax(-1), len(self.span_vals))
        out[ok] = cls[ok]
        return out

    def class_to_span(self, cls):
        cls = np.asarray(cls)
        vals = np.concatenate([self.span_vals, [self.rare_span]])
        return vals[cls]

    def soft_labels(self, y, sigma=0.004):
        """y: [N] -> [N, nb] gaussian soft labels over bin centers (rows of nan -> zeros)."""
        y = np.asarray(y, dtype=np.float64)
        lab = np.exp(-0.5 * ((self.centers[None, :] - y[:, None]) / sigma) ** 2)
        s = lab.sum(1, keepdims=True)
        lab = np.where(s > 0, lab / np.maximum(s, 1e-12), 0)
        return lab.astype(np.float32)


# ------------------------------------------------------------------ decoders (numpy, on probabilities over y bins)
def softmax(z, axis=-1):
    z = z - z.max(axis, keepdims=True)
    e = np.exp(z)
    return e / e.sum(axis, keepdims=True)


def decode_argmax(p, centers):
    return centers[p.argmax(-1)]


def decode_expect(p, centers):
    return (p * centers[None, :]).sum(-1)


def decode_window(p, centers, half_width_bins=4, refine=True):
    """Centre of the window (2*half+1 bins) holding the most probability mass; optional mass-weighted refinement.
    The window width equals the metric tolerance (+-0.01 of span) when bin_w=0.0025 and half=4."""
    k = 2 * half_width_bins + 1
    csum = np.cumsum(np.pad(p, ((0, 0), (1, 0))), axis=1)
    mass = csum[:, k:] - csum[:, :-k]  # window starting at i covers bins i..i+k-1
    start = mass.argmax(1)
    cidx = start + half_width_bins
    if not refine:
        return centers[cidx]
    out = np.empty(len(p))
    for n in range(len(p)):
        lo, hi = start[n], start[n] + k
        w = p[n, lo:hi]
        out[n] = (w * centers[lo:hi]).sum() / max(w.sum(), 1e-12)
    return out


def official_hits(pred, gt, rng):
    """Boolean hits exactly as the authors' loop (error <= 0.01 * range)."""
    err = np.abs(np.asarray(pred, np.float64) - np.asarray(gt, np.float64))
    return err <= 0.01 * np.asarray(rng, np.float64)


# ------------------------------------------------------------------ splits
def make_val_split(n, strata, n_val, seed=0):
    """Random stratified validation split (test is a random frame split of the same pool, see eda2): returns (train_idx, val_idx)."""
    rs = np.random.RandomState(seed)
    strata = np.asarray(strata)
    val = []
    for s in np.unique(strata):
        idx = np.where(strata == s)[0]
        k = int(round(n_val * len(idx) / n))
        val.extend(rs.choice(idx, size=min(k, len(idx)), replace=False).tolist())
    val = np.array(sorted(val))
    tr = np.setdiff1d(np.arange(n), val)
    return tr, val


def make_group_val_split(group_ids, n_val, seed=0):
    """Hold out whole groups (near-duplicate clusters) until >= n_val items are held out."""
    rs = np.random.RandomState(seed)
    gid = np.asarray(group_ids)
    ug, cnt = np.unique(gid, return_counts=True)
    order = rs.permutation(len(ug))
    held, tot = [], 0
    for o in order:
        if tot >= n_val:
            break
        held.append(ug[o])
        tot += cnt[o]
    val = np.where(np.isin(gid, held))[0]
    return np.setdiff1d(np.arange(len(gid)), val), val

# ======== src/jax_resnet.py ========
# Flax (linen) ResNet-18/34 whose submodule names mirror torchvision, so ImageNet weights and
# trained weights convert 1:1 in both directions (see convert_tv_to_flax / flax_to_tv_state_dict).
from functools import partial
from typing import Any, Sequence

import numpy as np
import jax
import jax.numpy as jnp
import flax.linen as nn

ARCH = {"resnet18": [2, 2, 2, 2], "resnet34": [3, 4, 6, 3]}
WIDTHS = [64, 128, 256, 512]


class BasicBlock(nn.Module):
    features: int
    stride: int = 1
    has_down: bool = False
    dtype: Any = jnp.float32

    @nn.compact
    def __call__(self, x, train: bool):
        conv = partial(nn.Conv, use_bias=False, dtype=self.dtype, param_dtype=jnp.float32)
        norm = partial(nn.BatchNorm, use_running_average=not train, momentum=0.9, epsilon=1e-5,
                       dtype=self.dtype, param_dtype=jnp.float32)
        y = conv(self.features, (3, 3), (self.stride, self.stride), padding=((1, 1), (1, 1)), name="conv1")(x)
        y = norm(name="bn1")(y)
        y = nn.relu(y)
        y = conv(self.features, (3, 3), (1, 1), padding=((1, 1), (1, 1)), name="conv2")(y)
        y = norm(name="bn2")(y)
        if self.has_down:
            x = conv(self.features, (1, 1), (self.stride, self.stride), padding=((0, 0), (0, 0)), name="down_conv")(x)
            x = norm(name="down_bn")(x)
        return nn.relu(x + y)


class ResNetBackbone(nn.Module):
    arch: str = "resnet18"
    width_mult: float = 1.0
    dtype: Any = jnp.float32

    @nn.compact
    def __call__(self, x, train: bool):
        """x: [B,H,W,3] already normalised. Returns the final feature map [B,H/32,W/32,C]."""
        widths = [int(round(w * self.width_mult)) for w in WIDTHS]
        stem = widths[0]
        x = x.astype(self.dtype)
        x = nn.Conv(stem, (7, 7), (2, 2), padding=((3, 3), (3, 3)), use_bias=False, dtype=self.dtype,
                    param_dtype=jnp.float32, name="conv1")(x)
        x = nn.BatchNorm(use_running_average=not train, momentum=0.9, epsilon=1e-5, dtype=self.dtype,
                         param_dtype=jnp.float32, name="bn1")(x)
        x = nn.relu(x)
        x = nn.max_pool(x, (3, 3), (2, 2), padding=((1, 1), (1, 1)))
        in_f = stem
        for li, (nb, f) in enumerate(zip(ARCH[self.arch], widths)):
            for bi in range(nb):
                stride = 2 if (bi == 0 and li > 0) else 1
                has_down = (bi == 0) and (stride != 1 or in_f != f)
                x = BasicBlock(f, stride, has_down, self.dtype, name=f"layer{li + 1}_{bi}")(x, train)
                in_f = f
        return x


# ---------------------------------------------------------------- torchvision <-> flax weight conversion
def _conv_to_flax(w):  # [O,I,kh,kw] -> [kh,kw,I,O]
    return np.asarray(w).transpose(2, 3, 1, 0)


def _conv_to_tv(k):
    return np.asarray(k).transpose(3, 2, 0, 1)


def convert_tv_to_flax(sd, arch="resnet18"):
    """torchvision ResNet state_dict (tensors or numpy) -> (params, batch_stats) for ResNetBackbone (fc dropped)."""
    g = lambda k: np.asarray(sd[k].detach().cpu().numpy() if hasattr(sd[k], "detach") else sd[k])
    params, stats = {}, {}

    def bn(dst_p, dst_s, name, prefix):
        dst_p[name] = {"scale": g(prefix + ".weight"), "bias": g(prefix + ".bias")}
        dst_s[name] = {"mean": g(prefix + ".running_mean"), "var": g(prefix + ".running_var")}

    params["conv1"] = {"kernel": _conv_to_flax(g("conv1.weight"))}
    bn(params, stats, "bn1", "bn1")
    for li, nb in enumerate(ARCH[arch]):
        for bi in range(nb):
            tv = f"layer{li + 1}.{bi}"
            nm = f"layer{li + 1}_{bi}"
            p, s = {}, {}
            p["conv1"] = {"kernel": _conv_to_flax(g(tv + ".conv1.weight"))}
            bn(p, s, "bn1", tv + ".bn1")
            p["conv2"] = {"kernel": _conv_to_flax(g(tv + ".conv2.weight"))}
            bn(p, s, "bn2", tv + ".bn2")
            if (tv + ".downsample.0.weight") in sd:
                p["down_conv"] = {"kernel": _conv_to_flax(g(tv + ".downsample.0.weight"))}
                bn(p, s, "down_bn", tv + ".downsample.1")
            params[nm], stats[nm] = p, s
    return params, stats


def flax_to_tv_state_dict(params, stats, arch="resnet18"):
    """Inverse of convert_tv_to_flax: returns a dict of numpy arrays with torchvision names (no fc)."""
    sd = {}
    a = lambda x: np.asarray(x)

    def bn(prefix, p, s):
        sd[prefix + ".weight"] = a(p["scale"])
        sd[prefix + ".bias"] = a(p["bias"])
        sd[prefix + ".running_mean"] = a(s["mean"])
        sd[prefix + ".running_var"] = a(s["var"])
        sd[prefix + ".num_batches_tracked"] = np.array(0, dtype=np.int64)

    sd["conv1.weight"] = _conv_to_tv(a(params["conv1"]["kernel"]))
    bn("bn1", params["bn1"], stats["bn1"])
    for li, nb in enumerate(ARCH[arch]):
        for bi in range(nb):
            tv = f"layer{li + 1}.{bi}"
            nm = f"layer{li + 1}_{bi}"
            p, s = params[nm], stats[nm]
            sd[tv + ".conv1.weight"] = _conv_to_tv(a(p["conv1"]["kernel"]))
            bn(tv + ".bn1", p["bn1"], s["bn1"])
            sd[tv + ".conv2.weight"] = _conv_to_tv(a(p["conv2"]["kernel"]))
            bn(tv + ".bn2", p["bn2"], s["bn2"])
            if "down_conv" in p:
                sd[tv + ".downsample.0.weight"] = _conv_to_tv(a(p["down_conv"]["kernel"]))
                bn(tv + ".downsample.1", p["down_bn"], s["down_bn"])
    return sd

